async function main() {
  const config = parseConfig();
  if (!config.ok) {
    process.stderr.write(`[client] config error: ${config.error}
`);
    import_electron16.app.exit(1);
    return;
  }
  if (config.mode === "solo") {
    await runSoloMode();
    return;
  }
  if (config.mode === "app") {
    if (TRACKING_ENABLED) {
      await warmup().catch(() => {
      });
    }
    await runAppMode();
    return;
  }
  if (config.mode === "legacy-generate") {
    await runLegacyFlow("generate", {
      serverUrl: config.serverUrl,
      overlay: config.overlay,
      devStatus: config.devStatus
    });
    return;
  }
  await runLegacyFlow("redeem", {
    serverUrl: config.serverUrl,
    overlay: config.overlay,
    devStatus: config.devStatus,
    code: config.code
  });
}
